import subprocess, random, sys

def segment(s, min_rep=1, min_len=1):
    # returns list of segments: ('lit', ch) or ('rep', block_str, count)
    res=[]
    end=len(s)
    while end>0:
        found=None
        for L in range(1, end//2+1):
            block=s[end-L:end]
            k=1
            while end-(k+1)*L>=0 and s[end-(k+1)*L:end-k*L]==block:
                k+=1
            if k-1>=min_rep:
                found=(L,block,k)
                break
        if found and found[0]>=min_len:
            L,block,k=found
            res.append(('rep',block,k))
            end-=L*k
        else:
            # if found but length too short, also falls here
            res.append(('lit', s[end-1]))
            end-=1
    res.reverse()
    return res

def render(s, min_rep=1, min_len=1):
    segs=segment(s,min_rep,min_len)
    out=""
    for seg in segs:
        if seg[0]=='lit':
            c=seg[1]
            out+= ('\\'+c if c in '.^$*+?()[]{}|\\-' else c)
        else:
            _,block,k=seg
            inner=render(block, min_rep, min_len)
            if len(block)==1:
                # char rendering
                out+=inner+"{"+str(k)+"}"
            else:
                out+="(?:%s){%d}"%(inner,k)
    return "^"+out+"$"

def orig(s, min_rep=1, min_len=1):
    args=["./executable","-r","--min-repetitions",str(min_rep),"--min-substring-length",str(min_len),s]
    p=subprocess.run(args,capture_output=True,text=True)
    return p.stdout.strip()

