mismatch=0; total=0
examples=[]
for trial in range(400):
    n=random.randint(1,10)
    s=''.join(random.choice("abc") for _ in range(n))
    pred=render(s); o=orig(s)
    total+=1
    if pred!=o:
        mismatch+=1
        if len(examples)<20: examples.append((s,pred,o,segment(s)))
print("total",total,"mismatch",mismatch)
for e in examples: print(e)
