import subprocess, random
from simrep import render_inner, orig

def segment2(s, min_rep=1, min_len=1, mode='maxcover'):
    res=[]; end=len(s)
    while end>0:
        cand=[]
        for L in range(1, end//2+1):
            block=s[end-L:end]
            k=1
            while end-(k+1)*L>=0 and s[end-(k+1)*L:end-k*L]==block:
                k+=1
            if k-1>=min_rep:
                cand.append((L,block,k))
        found=None
        if cand:
            if mode=='smallest': found=cand[0]
            elif mode=='largest': found=cand[-1]
            elif mode=='maxcover': found=max(cand, key=lambda x:(x[2]*x[0], -x[0]))
            elif mode=='maxcover_small_firstchar': found=max(cand, key=lambda x:(x[2]*x[0], -x[0]))
        if found and found[0]>=min_len:
            L,block,k=found; res.append(('rep',block,k)); end-=L*k
        else:
            res.append(('lit',s[end-1])); end-=1
    res.reverse(); return res

def render2(s, mode='maxcover', min_rep=1, min_len=1, expand_rule=False):
    segs=segment2(s,min_rep,min_len,mode)
    if expand_rule:
        new=[]
        for i,seg in enumerate(segs):
            if seg[0]=='rep' and len(seg[1])==1 and i+1<len(segs) and segs[i+1][0]=='rep' and len(segs[i+1][1])>1 and segs[i+1][1][0]==seg[1]:
                # expand to lits
                for ch in seg[1]*seg[2]: new.append(('lit',ch))
            else:
                new.append(seg)
        segs=new
    out=""
    for seg in segs:
        if seg[0]=='lit': out+=seg[1]
        else:
            _,block,k=seg
            inner=render2(block, mode, min_rep, min_len, expand_rule=False) if len(block)>1 else block
            # for inner, use segment2 render manually
            if len(block)>1:
                # compute inner via recursion on render2 without anchors: render2 returns full string segment (no anchors)
                pass
            out+= (inner+"{"+str(k)+"}") if len(block)==1 else ("(?:%s){%d}"%(inner,k))
    return "^"+out+"$"

# render2 recursion already returns ^$; fix by making inner function
def render_mode(s, mode, min_rep=1, min_len=1, expand_rule=False):
    def rec(st):
        segs=segment2(st,min_rep,min_len,mode)
        if expand_rule:
            new=[]
            for i,seg in enumerate(segs):
                if seg[0]=='rep' and len(seg[1])==1 and i+1<len(segs) and segs[i+1][0]=='rep' and len(segs[i+1][1])>1 and segs[i+1][1][0]==seg[1]:
                    for ch in seg[1]*seg[2]: new.append(('lit',ch))
                else: new.append(seg)
            segs=new
        out=""
        for seg in segs:
            if seg[0]=='lit': out+=seg[1]
            else:
                _,block,k=seg
                inn=block if len(block)==1 else rec(block)
                out+= inn+"{"+str(k)+"}" if len(block)==1 else "(?:%s){%d}"%(inn,k)
        return out
    return "^"+rec(s)+"$"

for mode in ['smallest','largest','maxcover']:
    for expand in [False,True]:
        random.seed(0); mism=0; ex=[]
        for trial in range(300):
            n=random.randint(1,11); s=''.join(random.choice("abc") for _ in range(n))
            pred=render_mode(s,mode,expand_rule=expand); o=orig(s)
            if pred!=o:
                mism+=1
                if len(ex)<5: ex.append((s,pred,o))
        print(mode, "expand",expand,"mism",mism, ex[:3])
