import json, re, sys
from collections import deque

EPS=('eps',)
def Char(c): return ('char',c)
def Class(chars): return ('class', frozenset(chars))
def Alt(members): return ('alt', tuple(members))
def Concat(parts): return ('concat', tuple(parts))
def Opt(e): return ('opt', e)
