    if t=='concat': return sum(matched_min_len(p) for p in e[1])
    if t=='opt': return 0
    return 0

# Config globals
CONFIG={'alt_flatten':True, 'factor':'both', 'sort':'maxlen'}

def mk_concat(a,b):
