# ---- DFA ----
class State:
    __slots__=('final','trans')
    def __init__(self, final, trans):
        self.final=final; self.trans=trans # dict char->state index in canonical list

def build_min_dfa(strings):
    # trie nodes: list of [final, dict char->node]
    nodes=[[False,{}]]
    for s in strings:
        if s=='':
            continue
        cur=0
        for ch in s:
            nxt=nodes[cur][1].get(ch)
            if nxt is None:
                nxt=len(nodes); nodes.append([False,{}]); nodes[cur][1][ch]=nxt
            cur=nxt
        nodes[cur][0]=True
    # canonical merge bottom up: process nodes in reverse order (children have higher index than parent in trie creation? yes node indices increase along path, so reverse works)
    canon_id=[-1]*len(nodes)
    sig_to_id={}
    states=[] # list State
    for i in range(len(nodes)-1,-1,-1):
        final, trans = nodes[i]
        sig=(final, tuple(sorted((ch, canon_id[child]) for ch,child in trans.items())))
        if sig in sig_to_id:
            cid=sig_to_id[sig]
        else:
            cid=len(states); sig_to_id[sig]=cid; states.append(None) # placeholder
        canon_id[i]=cid
    # Build states; need order states by cid as assigned in reverse processing (that's weird). Let's instead rebuild mapping cid->state using representative
    state_objs={}
    for i in range(len(nodes)):
        cid=canon_id[i]
        if cid not in state_objs:
            final, trans=nodes[i]
            state_objs[cid]=State(final, {ch:canon_id[child] for ch,child in sorted(trans.items())})
    root=canon_id[0]
    return state_objs, root

def state_features(state_objs, root):
    # BFS order from root sorted trans
    bfs={}; order=[]
    dq=deque([root]); bfs[root]=0
    while dq:
        u=dq.popleft(); order.append(u)
        for ch,v in sorted(state_objs[u].trans.items()):
            if v not in bfs:
                bfs[v]=len(bfs); dq.append(v)
    # distance/height to final leaf? compute longest path to a final state? Graph DAG towards... Use languages: compute set of strings? small dataset only.
    lang={}
    def compute(u, seen):
        if u in lang: return lang[u]
        st=state_objs[u]
        res=set()
        if st.final: res.add("")
        for ch,v in st.trans.items():
            for suffix in compute(v, seen):
                res.add(ch+suffix)
        lang[u]=res; return res
    for u in state_objs: compute(u, None)
    height={u: max((len(x) for x in lang[u]), default=0) for u in state_objs}
    minlen={u: min((len(x) for x in lang[u]), default=0) for u in state_objs}
    return {'bfs':bfs, 'order':order, 'lang':lang, 'height':height, 'minlen':minlen}

def eliminate_order(state_objs, root, feats, scheme):
    states=list(state_objs.keys())
    bfs=feats['bfs']; height=feats['height']; lang=feats['lang']
    # exclude root? root may be eliminated as intermediate too in GNFA (super start handles). But we will include all DFA states as eliminable.
    if scheme=='height_asc':
        return sorted(states, key=lambda u:(height[u], bfs.get(u,999)))
    if scheme=='height_desc':
        return sorted(states, key=lambda u:(-height[u], bfs.get(u,999)))
    if scheme=='bfs':
        return sorted(states, key=lambda u:bfs.get(u,999))
    if scheme=='bfs_rev':
        return sorted(states, key=lambda u:-bfs.get(u,999))
    if scheme=='height_asc_lang':
        return sorted(states, key=lambda u:(height[u], sorted(lang[u])))
    if scheme=='lang':
        return sorted(states, key=lambda u: sorted(lang[u]))
    if scheme=='id':
        return sorted(states)
    if scheme=='id_rev':
        return sorted(states, reverse=True)
    return states

def generate(strings, scheme='height_asc'):
    strings=[s for s in strings if s!='']
