                del edges[key]
        for i,j,prod in new_edges:
            add_edge(i,j,prod)
    final=edges.get((SS,SF), EPS)
    return "^"+print_expr(final)+"$"

def main():
    with open("/tmp/dataset.json") as f: data=json.load(f)
    schemes=['height_asc','height_desc','bfs','bfs_rev','id','id_rev','lang','height_asc_lang']
    import itertools
    for scheme in schemes:
        for factor in ['suffix','both','both_prefix_first','prefix','none']:
            CONFIG['factor']=factor
            correct=0; examples=[]
            for cases, expected in data:
                try:
                    got=generate(cases, scheme)
                except Exception as ex:
                    got=f"ERR {ex}"
                if got==expected: correct+=1
                elif len(examples)<3: examples.append((cases,expected,got))
            print(f"scheme={scheme} factor={factor} correct={correct}/{len(data)}")
            for e in examples: print("  ",e)

if __name__=='__main__': main()
