        # deterministic order: by bfs?
        preds_sorted=sorted(set(preds), key=lambda u: feats['bfs'].get(u, -999 if u==SS else 999))
        succs_sorted=sorted(set(succs), key=lambda u: feats['bfs'].get(u, 9999 if u==SF else 999))
        new_edges=[]
        for i in preds_sorted:
            for j in succs_sorted:
                prod=mk_concat(edges[(i,k)], edges[(k,j)])
                new_edges.append((i,j,prod))
        # remove all edges incident to k
        for key in list(edges.keys()):
            if key[0]==k or key[1]==k:
                del edges[key]
        for i,j,prod in new_edges:
            add_edge(i,j,prod)
    final=edges.get((SS,SF), EPS)
    return "^"+print_expr(final)+"$"

