import sim
from sim import *
CONFIG['factor']='both'; CONFIG['distribute_eps']=False; CONFIG['target_final_leaf']=False; CONFIG['pair_factor']=True; CONFIG['pair_eps_only']=True

def trav_order(state_objs, root, scheme):
    kind, nbr = scheme
    # Build forward adjacency sorted
    def fwd_neighbors(u):
        items=list(state_objs[u].trans.items()) # char->target
        if nbr=='sym_asc': items.sort(key=lambda x:x[0])
        elif nbr=='sym_desc': items.sort(key=lambda x:-ord(x[0]))
        elif nbr=='target_lang': 
            feats=None
            items.sort(key=lambda x:x[0])
        return [v for _,v in items]
    # reverse adjacency: for node u, predecessors p with symbol
    rev={u:[] for u in state_objs}
    for u,st in state_objs.items():
        for ch,v in st.trans.items(): rev[v].append((ch,u))
    def rev_neighbors(u):
        items=list(rev[u])
        if nbr in ('sym_asc',): items.sort(key=lambda x:x[0])
        elif nbr in ('sym_desc',): items.sort(key=lambda x:-ord(x[0]))
        elif nbr=='pred_bfs': items.sort(key=lambda x:x[0])
        return [p for _,p in items]
    leaf=[u for u,st in state_objs.items() if st.final and not st.trans][0]
    order=[]
    visited=set()
    def dfs(u, neighbors, post):
        # iterative recursion
        if u in visited: return
        visited.add(u)
        if not post: order.append(u)
        for v in neighbors(u):
            dfs(v, neighbors, post)
        if post: order.append(u)
    if kind=='rev_dfs_pre': dfs(leaf, rev_neighbors, False)
    elif kind=='rev_dfs_post': dfs(leaf, rev_neighbors, True)
    elif kind=='fwd_dfs_pre': dfs(root, fwd_neighbors, False)
    elif kind=='fwd_dfs_post': dfs(root, fwd_neighbors, True)
    elif kind=='rev_bfs':
        from collections import deque
        dq=deque([leaf]); visited={leaf}; order=[leaf]
        while dq:
            u=dq.popleft()
            for v in rev_neighbors(u):
                if v not in visited:
                    visited.add(v); order.append(v); dq.append(v)
    elif kind=='fwd_bfs':
        from collections import deque
        dq=deque([root]); visited={root}; order=[root]
        while dq:
            u=dq.popleft()
            for v in fwd_neighbors(u):
                if v not in visited:
                    visited.add(v); order.append(v); dq.append(v)
    # add unvisited at end
    for u in state_objs:
        if u not in order: order.append(u)
    return order

