import sim
from sim import *

def gen_v2(strings, scheme='height_asc', target_order='bfs'):
    strings=[s for s in strings if s!='']
    if not strings: return "^$"
    state_objs, root = build_min_dfa(strings)
    feats=state_features(state_objs, root)
    SS=-1
    accepting=[u for u,st in state_objs.items() if st.final]
    # order accepting targets
    bfs=feats['bfs']; height=feats['height']
    if target_order=='bfs': accepting.sort(key=lambda u:bfs.get(u,999))
    elif target_order=='bfs_rev': accepting.sort(key=lambda u:-bfs.get(u,999))
    elif target_order=='height': accepting.sort(key=lambda u:(height[u], bfs.get(u,999)))
    elif target_order=='height_desc': accepting.sort(key=lambda u:(-height[u], bfs.get(u,999)))
    elif target_order=='lang': accepting.sort(key=lambda u: sorted(feats['lang'][u]))
    results=[]
    for t in accepting:
        edges={}
        def add_edge(i,j,e):
            if (i,j) in edges: edges[(i,j)]=mk_alt(edges[(i,j)], e)
            else: edges[(i,j)]=e
        add_edge(SS, root, EPS)
        for u,st in state_objs.items():
            by_target={}
            for ch,v in st.trans.items(): by_target.setdefault(v,[]).append(ch)
            for v,chars in by_target.items():
                chars=sorted(chars)
                if len(chars)==1: e=Char(chars[0])
                else:
                    e=Char(chars[0])
                    for c in chars[1:]: e=mk_alt(e, Char(c))
