use crate::unicode_tables::{DIGIT_RANGES, WORD_RANGES};

#[derive(Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash, Debug)]
pub enum Symbol {
    Char(char),
    Shorthand(u8),
    Escaped(char),
    EscapedUnit(u16),
}

fn in_ranges(cp: u32, ranges: &[(u32, u32)]) -> bool {
    let mut lo = 0usize;
    let mut hi = ranges.len();
    while lo < hi {
        let mid = (lo + hi) / 2;
        let (a, b) = ranges[mid];
        if cp < a {
            hi = mid;
        } else if cp > b {
            lo = mid + 1;
        } else {
            return true;
        }
    }
    false
}

pub fn is_digit_char(c: char) -> bool {
    in_ranges(c as u32, DIGIT_RANGES)
}

pub fn is_word_char(c: char) -> bool {
    in_ranges(c as u32, WORD_RANGES)
}

pub fn escape_literal(c: char, verbose: bool, in_class: bool) -> String {
    match c {
        '\t' => return "\\t".to_string(),
        '\n' => return "\\n".to_string(),
        '\r' => return "\\r".to_string(),
        '\u{b}' => return "\\v".to_string(),
        '\u{c}' => return "\\f".to_string(),
        _ => {}
    }
    if verbose && c == ' ' {
        return "\\ ".to_string();
    }
    if verbose && c == '#' {
        return "\\#".to_string();
    }
    let needs_escape = if in_class {
        matches!(c, '$' | '-' | '[' | '\\' | ']' | '^')
    } else {
        matches!(
            c,
            '$' | '(' | ')' | '*' | '+' | '.' | '?' | '[' | '\\' | ']' | '^' | '{' | '|' | '}' | '-'
        )
    };
    if needs_escape {
        let mut s = String::with_capacity(2);
        s.push('\\');
        s.push(c);
        s
    } else {
        c.to_string()
    }
}

impl Symbol {
    pub fn render(&self, verbose: bool) -> String {
        match *self {
            Symbol::Char(c) => escape_literal(c, verbose, false),
            Symbol::Shorthand(kind) => {
                let mut s = String::with_capacity(2);
                s.push('\\');
                s.push(kind as char);
                s
            }
            Symbol::Escaped(c) => format!("\\u{{{:x}}}", c as u32),
            Symbol::EscapedUnit(u) => format!("\\u{{{:x}}}", u),
        }
    }

    pub fn class_char(&self) -> Option<char> {
        match *self {
            Symbol::Char(c) => Some(c),
            _ => None,
        }
    }
}

#[derive(Clone, PartialEq, Eq, PartialOrd, Ord, Hash, Debug)]
pub enum Elem {
    Atom(Symbol),
    RepSingle(Symbol, u32),
    RepBlock(Vec<Elem>, u32),
}

impl Elem {
    pub fn first_symbol(&self) -> Symbol {
        match self {
            Elem::Atom(s) => *s,
            Elem::RepSingle(s, _) => *s,
            Elem::RepBlock(block, _) => block
                .first()
                .map(|e| e.first_symbol())
                .unwrap_or(Symbol::Char('\0')),
        }
    }

    pub fn max_len(&self) -> u64 {
        match self {
            Elem::Atom(_) => 1,
            Elem::RepSingle(_, c) => *c as u64,
            Elem::RepBlock(block, c) => {
                block.iter().map(|e| e.max_len()).sum::<u64>() * (*c as u64)
            }
        }
    }
}
EOF
echo ok"}

