{"command":"cat > src/expression.rs <<'EOF'
use crate::symbol::{escape_literal, Symbol};
use std::collections::BTreeSet;

#[derive(Clone, Copy, Debug)]
pub struct RenderCfg {
    pub capture: bool,
    pub colorize: bool,
}

pub fn col(code: &str, text: &str, cfg: RenderCfg) -> String {
    col_flag(code, text, cfg.colorize)
}

pub fn col_flag(code: &str, text: &str, colorize: bool) -> String {
    if colorize {
        format!("\x1b[{}m{}\x1b[0m", code, text)
    } else {
        text.to_string()
    }
}

pub fn group_open(cfg: RenderCfg) -> String {
    col("1;32", if cfg.capture { "(" } else { "(?:" }, cfg)
}

pub fn group_close(cfg: RenderCfg) -> String {
    col("1;32", ")", cfg)
}

#[derive(Clone, PartialEq, Eq, Debug)]
pub enum Expr {
    Eps,
    Atom(Symbol),
    Class(BTreeSet<char>),
    Alt(Vec<Expr>),
    Concat(Vec<Expr>),
    Group(Box<Expr>),
    Repeated(Box<Expr>, u32, u32),
}

pub type ResExpr = Expr;

impl Expr {
    pub fn max_len(&self) -> u64 {
        match self {
            Expr::Eps => 0,
            Expr::Atom(_) | Expr::Class(_) => 1,
            Expr::Alt(members) => members.iter().map(|m| m.max_len()).max().unwrap_or(0),
            Expr::Concat(parts) => parts.iter().map(|p| p.max_len()).sum(),
            Expr::Group(inner) => inner.max_len(),
            Expr::Repeated(inner, _, hi) => inner.max_len().saturating_mul(*hi as u64),
        }
    }

    pub fn min_len(&self) -> u64 {
        match self {
            Expr::Eps => 0,
            Expr::Atom(_) | Expr::Class(_) => 1,
            Expr::Alt(members) => members.iter().map(|m| m.min_len()).min().unwrap_or(0),
            Expr::Concat(parts) => parts.iter().map(|p| p.min_len()).sum(),
            Expr::Group(inner) => inner.min_len(),
            Expr::Repeated(inner, lo, _) => inner.min_len().saturating_mul(*lo as u64),
        }
    }

    pub fn render_compact(&self, cfg: RenderCfg, verbose_escape: bool) -> String {
        match self {
            Expr::Eps => String::new(),
            Expr::Atom(sym) => {
                if let Symbol::Shorthand(_) = sym {
                    col("103;30", &sym.render(verbose_escape), cfg)
                } else {
                    sym.render(verbose_escape)
                }
            }
            Expr::Class(chars) => render_class(chars, cfg, verbose_escape),
            Expr::Alt(members) => render_alt(members, cfg, verbose_escape),
            Expr::Concat(parts) => parts
                .iter()
                .map(|p| p.render_compact(cfg, verbose_escape))
                .collect::<Vec<_>>()
                .join(""),
            Expr::Group(inner) => inner.render_compact(cfg, verbose_escape),
            Expr::Repeated(inner, lo, hi) => {
                render_repeated(inner, *lo, *hi, cfg, verbose_escape)
            }
        }
    }

    pub fn plain_string(&self) -> String {
        self.render_compact(
            RenderCfg {
                capture: false,
                colorize: false,
            },
            false,
        )
    }
}

fn quant_string(lo: u32, hi: u32) -> String {
    if lo == hi {
        format!("{{{}}}", lo)
    } else {
        format!("{{{},{}}}", lo, hi)
    }
}

fn render_repeated(inner: &Expr, lo: u32, hi: u32, cfg: RenderCfg, verbose_escape: bool) -> String {
    let q = col("104;37", &quant_string(lo, hi), cfg);
    match inner {
        Expr::Atom(_) | Expr::Class(_) | Expr::Alt(_) | Expr::Group(_) => {
            format!("{}{}", inner.render_compact(cfg, verbose_escape), q)
        }
        _ => {
            format!(
                "{}{}{}{}",
                group_open(cfg),
                inner.render_compact(cfg, verbose_escape),
                group_close(cfg),
                q
            )
        }
    }
}

pub fn render_optional(inner: &Expr, cfg: RenderCfg, verbose_escape: bool) -> String {
    let q = col("1;35", "?", cfg);
    match inner {
        Expr::Atom(_) | Expr::Class(_) => {
            format!("{}{}", inner.render_compact(cfg, verbose_escape), q)
        }
        Expr::Alt(_) => {
            format!("{}{}", inner.render_compact(cfg, verbose_escape), q)
        }
        _ => {
            format!(
                "{}{}{}{}",
                group_open(cfg),
                inner.render_compact(cfg, verbose_escape),
                group_close(cfg),
                q
            )
        }
    }
}

fn render_alt(members: &[Expr], cfg: RenderCfg, verbose_escape: bool) -> String {
    if members.iter().any(|m| matches!(m, Expr::Eps)) {
        let rest: Vec<&Expr> = members.iter().filter(|m| !matches!(m, Expr::Eps)).collect();
        if rest.is_empty() {
            return String::new();
        }
        if rest.len() == 1 {
            return render_optional(rest[0], cfg, verbose_escape);
        }
        let inner = Expr::Alt(rest.iter().map(|e| (*e).clone()).collect());
        let q = col("1;35", "?", cfg);
        return format!("{}{}", inner.render_compact(cfg, verbose_escape), q);
    }
    let mut out = group_open(cfg);
    for (i, m) in members.iter().enumerate() {
        if i > 0 {
            out.push_str(&col("1;31", "|", cfg));
        }
        out.push_str(&m.render_compact(cfg, verbose_escape));
    }
    out.push_str(&group_close(cfg));
    out
}

pub fn render_class(chars: &BTreeSet<char>, cfg: RenderCfg, verbose_escape: bool) -> String {
    let vec: Vec<char> = chars.iter().copied().collect();
    let mut out = col("1;36", "[", cfg);
    let mut i = 0usize;
    while i < vec.len() {
        let mut j = i;
        while j + 1 < vec.len() && (vec[j + 1] as u32) == (vec[j] as u32) + 1 {
            j += 1;
        }
        if j - i + 1 >= 3 {
            out.push_str(&escape_literal(vec[i], verbose_escape, true));
            out.push_str(&col("1;36", "-", cfg));
            out.push_str(&escape_literal(vec[j], verbose_escape, true));
        } else {
            for k in i..=j {
                out.push_str(&escape_literal(vec[k], verbose_escape, true));
            }
        }
        i = j + 1;
    }
    out.push_str(&col("1;36", "]", cfg));
    out
}

// ---------------- Constructors ----------------

pub fn seq_of(e: &Expr) -> Vec<Expr> {
    match e {
        Expr::Concat(parts) => parts.clone(),
        Expr::Eps => Vec::new(),
        other => vec![other.clone()],
    }
}

pub fn from_seq(parts: &[Expr]) -> Expr {
    match parts.len() {
        0 => Expr::Eps,
        1 => parts[0].clone(),
        _ => {
            let mut ps = parts.to_vec();
            wrap_alts(&mut ps);
            Expr::Concat(ps)
        }
    }
}

fn wrap_alts(parts: &mut [Expr]) {
    for p in parts.iter_mut() {
        if matches!(p, Expr::Alt(_)) {
            let old = std::mem::replace(p, Expr::Eps);
            *p = Expr::Group(Box::new(old));
        }
    }
}

pub fn mk_concat(a: &Expr, b: &Expr) -> Expr {
    if matches!(a, Expr::Eps) {
        return b.clone();
    }
    if matches!(b, Expr::Eps) {
        return a.clone();
    }
    let mut parts = seq_of(a);
    parts.extend(seq_of(b));
    if parts.len() == 1 {
        return parts.into_iter().next().unwrap();
    }
    wrap_alts(&mut parts);
