use crate::symbol::{escape_literal, Symbol};
use std::collections::BTreeSet;

#[derive(Clone, Copy, Debug)]
pub struct RenderCfg {
    pub capture: bool,
    pub colorize: bool,
}

pub fn col(code: &str, text: &str, cfg: RenderCfg) -> String {
    col_flag(code, text, cfg.colorize)
}

pub fn col_flag(code: &str, text: &str, colorize: bool) -> String {
    if colorize {
        format!("\x1b[{}m{}\x1b[0m", code, text)
    } else {
        text.to_string()
    }
}

pub fn group_open(cfg: RenderCfg) -> String {
    col("1;32", if cfg.capture { "(" } else { "(?:" }, cfg)
}

pub fn group_close(cfg: RenderCfg) -> String {
    col("1;32", ")", cfg)
}

#[derive(Clone, PartialEq, Eq, Debug)]
pub enum Expr {
    Eps,
    Atom(Symbol),
    Class(BTreeSet<char>),
    Alt(Vec<Expr>),
    Concat(Vec<Expr>),
    Group(Box<Expr>),
    Repeated(Box<Expr>, u32, u32),
}

pub type ResExpr = Expr;

impl Expr {
    pub fn max_len(&self) -> u64 {
        match self {
            Expr::Eps => 0,
            Expr::Atom(_) | Expr::Class(_) => 1,
            Expr::Alt(members) => members.iter().map(|m| m.max_len()).max().unwrap_or(0),
            Expr::Concat(parts) => parts.iter().map(|p| p.max_len()).sum(),
            Expr::Group(inner) => inner.max_len(),
            Expr::Repeated(inner, _, hi) => inner.max_len().saturating_mul(*hi as u64),
        }
    }

    pub fn min_len(&self) -> u64 {
        match self {
            Expr::Eps => 0,
            Expr::Atom(_) | Expr::Class(_) => 1,
            Expr::Alt(members) => members.iter().map(|m| m.min_len()).min().unwrap_or(0),
            Expr::Concat(parts) => parts.iter().map(|p| p.min_len()).sum(),
            Expr::Group(inner) => inner.min_len(),
            Expr::Repeated(inner, lo, _) => inner.min_len().saturating_mul(*lo as u64),
        }
    }

    pub fn render_compact(&self, cfg: RenderCfg, verbose_escape: bool) -> String {
        match self {
            Expr::Eps => String::new(),
            Expr::Atom(sym) => {
                if let Symbol::Shorthand(_) = sym {
                    col("103;30", &sym.render(verbose_escape), cfg)
                } else {
                    sym.render(verbose_escape)
                }
            }
            Expr::Class(chars) => render_class(chars, cfg, verbose_escape),
            Expr::Alt(members) => render_alt(members, cfg, verbose_escape),
            Expr::Concat(parts) => parts
                .iter()
                .map(|p| p.render_compact(cfg, verbose_escape))
                .collect::<Vec<_>>()
                .join(""),
            Expr::Group(inner) => inner.render_compact(cfg, verbose_escape),
            Expr::Repeated(inner, lo, hi) => {
                render_repeated(inner, *lo, *hi, cfg, verbose_escape)
            }
        }
    }

    pub fn plain_string(&self) -> String {
        self.render_compact(
            RenderCfg {
                capture: false,
                colorize: false,
            },
            false,
        )
    }
}

fn quant_string(lo: u32, hi: u32) -> String {
    if lo == hi {
        format!("{{{}}}", lo)
    } else {
        format!("{{{},{}}}", lo, hi)
    }
}

