    let q = col("104;37", &quant_string(lo, hi), cfg);
    match inner {
        Expr::Atom(_) | Expr::Class(_) | Expr::Alt(_) | Expr::Group(_) => {
            format!("{}{}", inner.render_compact(cfg, verbose_escape), q)
        }
        _ => {
            format!(
                "{}{}{}{}",
                group_open(cfg),
                inner.render_compact(cfg, verbose_escape),
                group_close(cfg),
                q
            )
        }
    }
