        let inner = Expr::Alt(rest.iter().map(|e| (*e).clone()).collect());
        let q = col("1;35", "?", cfg);
        return format!("{}{}", inner.render_compact(cfg, verbose_escape), q);
    }
    let mut out = group_open(cfg);
    for (i, m) in members.iter().enumerate() {
        if i > 0 {
            out.push_str(&col("1;31", "|", cfg));
        }
        out.push_str(&m.render_compact(cfg, verbose_escape));
    }
    out.push_str(&group_close(cfg));
    out
}

pub fn render_class(chars: &BTreeSet<char>, cfg: RenderCfg, verbose_escape: bool) -> String {
    let vec: Vec<char> = chars.iter().copied().collect();
    let mut out = col("1;36", "[", cfg);
    let mut i = 0usize;
    while i < vec.len() {
