pub fn from_seq(parts: &[Expr]) -> Expr {
    match parts.len() {
        0 => Expr::Eps,
        1 => parts[0].clone(),
        _ => {
            let mut ps = parts.to_vec();
            wrap_alts(&mut ps);
            Expr::Concat(ps)
        }
    }
}

fn wrap_alts(parts: &mut [Expr]) {
    for p in parts.iter_mut() {
        if matches!(p, Expr::Alt(_)) {
            let old = std::mem::replace(p, Expr::Eps);
            *p = Expr::Group(Box::new(old));
        }
    }
}

pub fn mk_concat(a: &Expr, b: &Expr) -> Expr {
    if matches!(a, Expr::Eps) {
        return b.clone();
    }
    if matches!(b, Expr::Eps) {
        return a.clone();
    }
    let mut parts = seq_of(a);
    parts.extend(seq_of(b));
    if parts.len() == 1 {
        return parts.into_iter().next().unwrap();
    }
    wrap_alts(&mut parts);
    Expr::Concat(parts)
}

fn sort_members(members: &mut Vec<Expr>) {
    members.sort_by(|x, y| {
        let kx = (std::cmp::Reverse(x.max_len()), x.min_len(), x.plain_string());
        let ky = (std::cmp::Reverse(y.max_len()), y.min_len(), y.plain_string());
        kx.cmp(&ky)
    });
}

pub fn build_alt(members_in: Vec<Expr>) -> Expr {
    let mut members: Vec<Expr> = Vec::new();
    for m in members_in {
        if !members.contains(&m) {
            members.push(m);
        }
    }
    if members.len() == 1 {
        return members.into_iter().next().unwrap();
    }
    let has_eps = members.iter().any(|m| matches!(m, Expr::Eps));
    let non_eps: Vec<&Expr> = members
        .iter()
        .filter(|m| !matches!(m, Expr::Eps))
        .collect();
    if non_eps.len() >= 2
        && non_eps.iter().all(|m| matches!(m, Expr::Atom(Symbol::Char(_)) | Expr::Class(_)))
    {
        let mut set = BTreeSet::new();
        for m in &non_eps {
            match m {
                Expr::Atom(Symbol::Char(c)) => {
                    set.insert(*c);
                }
                Expr::Class(s) => {
                    for c in s {
                        set.insert(*c);
                    }
                }
                _ => unreachable!(),
            }
        }
        let cls = Expr::Class(set);
        if has_eps {
            let mut v = vec![Expr::Eps, cls];
            sort_members(&mut v);
            return Expr::Alt(v);
        }
        return cls;
    }
    if members.len() == 1 {
        return members.into_iter().next().unwrap();
    }
    sort_members(&mut members);
    Expr::Alt(members)
}

fn try_factor(a: &Expr, b: &Expr) -> Option<Expr> {
    let sa = seq_of(a);
    let sb = seq_of(b);
    let mut p = 0usize;
    while p < sa.len().min(sb.len()) && sa[p] == sb[p] {
        p += 1;
    }
    let mut sfx = 0usize;
    while sfx < sa.len().min(sb.len()) && sa[sa.len() - 1 - sfx] == sb[sb.len() - 1 - sfx] {
        sfx += 1;
    }
    if p == 0 && sfx == 0 {
        return None;
    }
    // Prefer suffix on tie.
    if sfx >= p && sfx > 0 {
        if sfx <= sa.len().min(sb.len()) {
            let ra = &sa[..sa.len() - sfx];
            let rb = &sb[..sb.len() - sfx];
            let suffix = &sa[sa.len() - sfx..];
            let inner = if ra.is_empty() && rb.is_empty() {
                Expr::Eps
            } else {
                mk_alt(&from_seq(ra), &from_seq(rb))
            };
            return Some(mk_concat(&inner, &from_seq(suffix)));
        }
    }
    if p > 0 {
        let ra = &sa[p..];
        let rb = &sb[p..];
        let prefix = &sa[..p];
        let inner = if ra.is_empty() && rb.is_empty() {
            Expr::Eps
        } else {
            mk_alt(&from_seq(ra), &from_seq(rb))
        };
        return Some(mk_concat(&from_seq(prefix), &inner));
    }
    None
}

pub fn mk_alt(a: &Expr, b: &Expr) -> Expr {
    if a == b {
        return a.clone();
    }
    if let Some(f) = try_factor(a, b) {
        return f;
    }
    // Pair-factor against individual members of a nullable alternation.
    for (alt_side, other) in [(a, b), (b, a)] {
        if let Expr::Alt(members) = alt_side {
            if members.iter().any(|m| matches!(m, Expr::Eps)) {
                let mut existing = members.clone();
                let other_members: Vec<Expr> = match other {
                    Expr::Alt(ms) => ms.clone(),
                    o => vec![o.clone()],
                };
                let mut changed = false;
                let mut remaining: Vec<Expr> = Vec::new();
                for term in &other_members {
                    if matches!(term, Expr::Eps) {
                        remaining.push(term.clone());
                        continue;
                    }
                    let mut placed = false;
                    for i in 0..existing.len() {
                        if matches!(existing[i], Expr::Eps) {
                            continue;
                        }
                        if let Some(f) = try_factor(&existing[i], term) {
                            existing[i] = f;
                            placed = true;
                            changed = true;
                            break;
                        }
                    }
                    if !placed {
                        remaining.push(term.clone());
                    }
                }
                if changed {
                    existing.extend(remaining);
                    return build_alt(existing);
                }
            }
            break;
        }
    }
    let mut members: Vec<Expr> = Vec::new();
    for e in [a, b] {
        match e {
            Expr::Alt(ms) => members.extend(ms.iter().cloned()),
            other => members.push(other.clone()),
        }
    }
    build_alt(members)
}
