        Expr::Group(inner) => needs_multiline(inner) || matches!(**inner, Expr::Alt(_)),
        Expr::Repeated(inner, _, _) => {
            !matches!(**inner, Expr::Atom(_) | Expr::Class(_))
        }
        Expr::Concat(_) => true,
        _ => false,
    }
}

