    let n = nodes.len();
    let mut canon: Vec<usize> = vec![usize::MAX; n];
    let mut sig_to_id: HashMap<(bool, Vec<(TransKey, usize)>), usize> = HashMap::new();
    let mut num_states = 0usize;
    for i in (0..n).rev() {
        let sig: (bool, Vec<(TransKey, usize)>) = (
            nodes[i].is_final,
            nodes[i]
                .trans
                .iter()
                .map(|(k, &child)| (k.clone(), canon[child]))
                .collect(),
        );
        if let Some(&id) = sig_to_id.get(&sig) {
            canon[i] = id;
        } else {
            let id = num_states;
            num_states += 1;
            sig_to_id.insert(sig, id);
            canon[i] = id;
        }
    }

    let mut states: BTreeMap<usize, State> = BTreeMap::new();
    for i in 0..n {
        let id = canon[i];
        states.entry(id).or_insert_with(|| State {
            is_final: nodes[i].is_final,
            trans: nodes[i]
                .trans
                .iter()
                .map(|(k, &child)| (k.clone(), canon[child]))
                .collect(),
        });
    }
    let root = canon[0];
    let state_ids: Vec<usize> = states.keys().copied().collect();

    // BFS order from root.
    let mut bfs: HashMap<usize, usize> = HashMap::new();
    let mut queue: VecDeque<usize> = VecDeque::new();
    bfs.insert(root, 0);
    queue.push_back(root);
    while let Some(u) = queue.pop_front() {
        let cur = bfs[&u];
        if let Some(st) = states.get(&u) {
            for (_, v) in &st.trans {
                if !bfs.contains_key(v) {
                    let idx = cur + 1;
                    // Use insertion sequence number, not depth, as tie break:
                    let seq_no = bfs.len();
                    let _ = idx;
                    bfs.insert(*v, seq_no);
                    queue.push_back(*v);
                }
            }
        }
    }
    for (idx, &id) in state_ids.iter().enumerate() {
        bfs.entry(id).or_insert(usize::MAX - idx);
    }

    // Heights (maximum matched length of the state's language).
    fn compute_height(
        u: usize,
        states: &BTreeMap<usize, State>,
        memo: &mut HashMap<usize, u64>,
        visiting: &mut BTreeSet<usize>,
    ) -> u64 {
        if let Some(&h) = memo.get(&u) {
            return h;
        }
        if !visiting.insert(u) {
            return 0;
        }
        let mut best = 0u64;
        if let Some(st) = states.get(&u) {
            for (key, v) in &st.trans {
                let cand = key
                    .max_len()
                    .saturating_add(compute_height(*v, states, memo, visiting));
                if cand > best {
                    best = cand;
                }
            }
        }
        visiting.remove(&u);
        memo.insert(u, best);
        best
    }
