    for e in elems {
        let ex = elem_to_expr(e);
        if first {
            result = ex;
            first = false;
        } else {
            result = mk_concat(&result, &ex);
        }
    }
    result
}

#[derive(Clone, Debug)]
struct TrieNode {
    is_final: bool,
    trans: BTreeMap<TransKey, usize>,
}

#[derive(Clone, Debug)]
struct State {
    is_final: bool,
    // sorted by TransKey
    trans: Vec<(TransKey, usize)>,
}

pub fn generate_expression(sequences: &[Vec<Elem>]) -> Expr {
    // Build trie.
    let mut nodes: Vec<TrieNode> = vec![TrieNode {
        is_final: false,
        trans: BTreeMap::new(),
    }];
    for seq in sequences {
        if seq.is_empty() {
            continue;
        }
        let mut cur = 0usize;
        for elem in seq {
            let key = TransKey::from_elem(elem);
            let next = if let Some(&n) = nodes[cur].trans.get(&key) {
                n
            } else {
                let n = nodes.len();
                nodes.push(TrieNode {
                    is_final: false,
                    trans: BTreeMap::new(),
                });
                nodes[cur].trans.insert(key, n);
                n
            };
            cur = next;
        }
        nodes[cur].is_final = true;
    }

    // Merge equivalent states bottom-up.
    let n = nodes.len();
    let mut canon: Vec<usize> = vec![usize::MAX; n];
    let mut sig_to_id: HashMap<(bool, Vec<(TransKey, usize)>), usize> = HashMap::new();
    let mut num_states = 0usize;
    for i in (0..n).rev() {
        let sig: (bool, Vec<(TransKey, usize)>) = (
            nodes[i].is_final,
            nodes[i]
                .trans
                .iter()
                .map(|(k, &child)| (k.clone(), canon[child]))
                .collect(),
        );
        if let Some(&id) = sig_to_id.get(&sig) {
            canon[i] = id;
        } else {
            let id = num_states;
            num_states += 1;
            sig_to_id.insert(sig, id);
            canon[i] = id;
        }
    }

    let mut states: BTreeMap<usize, State> = BTreeMap::new();
    for i in 0..n {
        let id = canon[i];
        states.entry(id).or_insert_with(|| State {
            is_final: nodes[i].is_final,
            trans: nodes[i]
                .trans
                .iter()
                .map(|(k, &child)| (k.clone(), canon[child]))
                .collect(),
        });
    }
    let root = canon[0];
    let state_ids: Vec<usize> = states.keys().copied().collect();

    // BFS order from root.
    let mut bfs: HashMap<usize, usize> = HashMap::new();
    let mut queue: VecDeque<usize> = VecDeque::new();
    bfs.insert(root, 0);
    queue.push_back(root);
    while let Some(u) = queue.pop_front() {
        let cur = bfs[&u];
        if let Some(st) = states.get(&u) {
            for (_, v) in &st.trans {
                if !bfs.contains_key(v) {
                    let idx = cur + 1;
                    // Use insertion sequence number, not depth, as tie break:
                    let seq_no = bfs.len();
                    let _ = idx;
                    bfs.insert(*v, seq_no);
                    queue.push_back(*v);
                }
            }
        }
    }
    for (idx, &id) in state_ids.iter().enumerate() {
        bfs.entry(id).or_insert(usize::MAX - idx);
    }

    // Heights (maximum matched length of the state's language).
    fn compute_height(
        u: usize,
        states: &BTreeMap<usize, State>,
        memo: &mut HashMap<usize, u64>,
        visiting: &mut BTreeSet<usize>,
    ) -> u64 {
        if let Some(&h) = memo.get(&u) {
            return h;
        }
        if !visiting.insert(u) {
            return 0;
        }
        let mut best = 0u64;
        if let Some(st) = states.get(&u) {
            for (key, v) in &st.trans {
                let cand = key
                    .max_len()
                    .saturating_add(compute_height(*v, states, memo, visiting));
                if cand > best {
                    best = cand;
                }
            }
        }
        visiting.remove(&u);
        memo.insert(u, best);
        best
    }
    let mut heights: HashMap<usize, u64> = HashMap::new();
    for &id in &state_ids {
        let mut memo = heights.clone();
        let h = compute_height(id, &states, &mut memo, &mut BTreeSet::new());
        heights = memo;
        heights.insert(id, h);
    }

    // GNFA setup.
    let ss = num_states + 1000000;
    let sf = num_states + 1000001;
    let mut edges: BTreeMap<(usize, usize), Expr> = BTreeMap::new();

    fn add_edge(edges: &mut BTreeMap<(usize, usize), Expr>, i: usize, j: usize, e: Expr) {
        if matches!(e, Expr::Eps) && i != j {
            // Epsilon edges are inserted as Eps below by caller handling;
            // this branch is not used for epsilon.
        }
        if let Some(old) = edges.get(&(i, j)).cloned() {
            let merged = mk_alt(&old, &e);
            edges.insert((i, j), merged);
        } else {
            edges.insert((i, j), e);
        }
    }

    add_edge(&mut edges, ss, root, Expr::Eps);
    for (&u, st) in states.iter() {
        // Group transitions by target, preserving key order.
        let mut groups: Vec<(usize, Vec<TransKey>)> = Vec::new();
        for (key, v) in &st.trans {
            if let Some(g) = groups.iter_mut().find(|(target, _)| target == v) {
                g.1.push(key.clone());
            } else {
                groups.push((*v, vec![key.clone()]));
            }
        }
        for (v, keys) in groups {
            let e = build_transition_expr(&keys);
            add_edge(&mut edges, u, v, e);
        }
        if st.is_final {
            add_edge(&mut edges, u, sf, Expr::Eps);
        }
    }

    let mut order = state_ids.clone();
    order.sort_by_key(|&u| (*heights.get(&u).unwrap_or(&0), *bfs.get(&u).unwrap_or(&usize::MAX)));

    for &k in &order {
        let preds: BTreeSet<usize> = edges
            .keys()
            .filter(|(_, j)| *j == k)
            .map(|(i, _)| *i)
            .filter(|&i| i != k)
            .collect();
        let succs: BTreeSet<usize> = edges
            .keys()
            .filter(|(i, _)| *i == k)
            .map(|(_, j)| *j)
            .filter(|&j| j != k)
            .collect();
        let mut preds_sorted: Vec<usize> = preds.into_iter().collect();
        preds_sorted.sort_by_key(|&u| {
            if u == ss {
                -1i64
            } else {
                *bfs.get(&u).unwrap_or(&usize::MAX) as i64
            }
        });
        let mut succs_sorted: Vec<usize> = succs.into_iter().collect();
        succs_sorted.sort_by_key(|&u| {
            if u == sf {
                i64::MAX
            } else {
                *bfs.get(&u).unwrap_or(&usize::MAX) as i64
            }
        });

        let mut new_edges: Vec<(usize, usize, Expr)> = Vec::new();
        for &i in &preds_sorted {
            for &j in &succs_sorted {
                if let (Some(eik), Some(ekj)) =
                    (edges.get(&(i, k)).cloned(), edges.get(&(k, j)).cloned())
                {
                    let prod = mk_concat(&eik, &ekj);
                    new_edges.push((i, j, prod));
                }
            }
        }
        edges.retain(|(i, j), _| *i != k && *j != k);
        for (i, j, prod) in new_edges {
            add_edge(&mut edges, i, j, prod);
        }
    }

    edges.get(&(ss, sf)).cloned().unwrap_or(Expr::Eps)
}

fn build_transition_expr(keys: &[TransKey]) -> Expr {
    // Partition by core.
    let mut by_core: Vec<(&Core, Vec<u32>)> = Vec::new();
    for key in keys {
        if let Some(entry) = by_core.iter_mut().find(|(c, _)| **c == key.core) {
            entry.1.push(key.count);
        } else {
            by_core.push((&key.core, vec![key.count]));
        }
    }
    let mut terms: Vec<Expr> = Vec::new();
    for (core, mut counts) in by_core {
        counts.sort_unstable();
        counts.dedup();
        // Partition into consecutive runs.
        let mut start = 0usize;
        for idx in 1..=counts.len() {
            if idx == counts.len() || counts[idx] != counts[idx - 1] + 1 {
                let lo = counts[start];
                let hi = counts[idx - 1];
                let term = match core {
                    Core::Single(sym) => {
                        if lo == 1 && hi == 1 {
                            Expr::Atom(*sym)
                        } else {
                            Expr::Repeated(Box::new(Expr::Atom(*sym)), lo, hi)
                        }
                    }
                    Core::Block(block) => {
                        let inner = sequence_to_expr(block);
                        Expr::Repeated(Box::new(inner), lo, hi)
                    }
                };
                terms.push(term);
                start = idx;
            }
        }
    }
    if terms.len() == 1 {
        return terms.into_iter().next().unwrap();
    }
    // Character class if every term is a single literal char.
    if !terms.is_empty()
        && terms
            .iter()
            .all(|t| matches!(t, Expr::Atom(Symbol::Char(_))))
    {
        return build_alt(terms);
    }
    let mut result = terms[0].clone();
    for t in terms.iter().skip(1) {
        result = mk_alt(&result, t);
    }
    result
}
EOF
echo ok"}

