use crate::dfa;
use crate::expression::{col, group_close, group_open, render_verbose, RenderCfg};
use crate::symbol::{is_digit_char, is_word_char, Elem, Symbol};

#[derive(Clone, Debug, Default)]
pub struct BuilderConfig {
    pub digits: bool,
    pub non_digits: bool,
    pub spaces: bool,
    pub non_spaces: bool,
    pub words: bool,
    pub non_words: bool,
    pub escape: bool,
    pub with_surrogates: bool,
    pub repetitions: bool,
    pub min_repetitions: u32,
    pub min_substring_length: u32,
    pub no_start_anchor: bool,
    pub no_end_anchor: bool,
    pub no_anchors: bool,
    pub verbose: bool,
    pub colorize: bool,
    pub ignore_case: bool,
    pub capture_groups: bool,
}

impl BuilderConfig {
    fn convert_char(&self, c: char) -> Option<Symbol> {
        let is_digit = is_digit_char(c);
        let is_space = c.is_whitespace();
        let is_word = is_word_char(c);
        // Priority (highest first) inferred from flag interactions:
        // digits/spaces, then words, then non-digits, then non-words, then non-spaces.
        let mut candidates: Vec<(u8, u8)> = Vec::new(); // (priority, shorthand letter)
        if is_digit && self.digits {
            candidates.push((6, b'd'));
        }
        if is_space && self.spaces {
            candidates.push((6, b's'));
        }
        if is_word && self.words {
            candidates.push((5, b'w'));
        }
        if !is_digit && self.non_digits {
            candidates.push((4, b'D'));
        }
        if !is_word && self.non_words {
            candidates.push((3, b'W'));
        }
        if !is_space && self.non_spaces {
            candidates.push((2, b'S'));
        }
        candidates.sort_by_key(|(p, _)| std::cmp::Reverse(*p));
        candidates
            .first()
            .map(|(_, letter)| Symbol::Shorthand(*letter))
    }

    fn char_to_symbols(&self, c: char, out: &mut Vec<Symbol>) {
        if let Some(sym) = self.convert_char(c) {
            out.push(sym);
            return;
        }
        if self.escape && !c.is_ascii() {
            let cp = c as u32;
            if self.with_surrogates && (0x10000..0x10ffff).contains(&cp) {
                let v = cp - 0x10000;
                let high = 0xd800u16 + ((v >> 10) as u16);
                let low = 0xdc00u16 + ((v & 0x3ff) as u16);
                out.push(Symbol::EscapedUnit(high));
                out.push(Symbol::EscapedUnit(low));
            } else {
                out.push(Symbol::Escaped(c));
            }
            return;
        }
        out.push(Symbol::Char(c));
    }
}

fn detect_repetitions(seq: &[Symbol], cfg: &BuilderConfig) -> Vec<Elem> {
    let min_repetitions = cfg.min_repetitions;
    let min_substring_length = cfg.min_substring_length;
    let mut result_rev: Vec<Elem> = Vec::new();
    let mut end = seq.len();
    while end > 0 {
        // Find candidate with maximum coverage.
        let mut best: Option<(usize, usize)> = None; // (L, k)
        let mut best_coverage = 0usize;
        for l in 1..=(end / 2) {
            let block = &seq[end - l..end];
            let mut k = 1usize;
            while end >= (k + 1) * l && &seq[end - (k + 1) * l..end - k * l] == block {
                k += 1;
            }
            if k >= 2 {
                let coverage = k * l;
                if coverage > best_coverage
                    || (coverage == best_coverage
                        && best.map(|(bl, _)| l < bl).unwrap_or(false))
                {
                    best = Some((l, k));
                    best_coverage = coverage;
                }
            }
        }
        if let Some((l, k)) = best {
            if (k as u64) - 1 >= (min_repetitions as u64) && (l as u64) >= (min_substring_length as u64) {
                let block = &seq[end - l..end];
                let elem = if l == 1 {
                    Elem::RepSingle(block[0], k as u32)
                } else {
                    Elem::RepBlock(detect_repetitions(block, cfg), k as u32)
                };
                result_rev.push(elem);
                end -= l * k;
                continue;
            } else if (l as u64) < (min_substring_length as u64) {
                // Consume the whole candidate as literals.
                let chunk = &seq[end - l * k..end];
                for sym in chunk.iter().rev() {
                    result_rev.push(Elem::Atom(*sym));
                }
                end -= l * k;
                continue;
            }
            // Otherwise fall through and emit a single symbol.
        }
        result_rev.push(Elem::Atom(seq[end - 1]));
        end -= 1;
    }
    result_rev.reverse();
    // Expand a single-symbol repetition immediately followed by a
    // block repetition whose block starts with the same symbol.
    let mut expanded: Vec<Elem> = Vec::new();
    let total = result_rev.len();
    for (i, elem) in result_rev.into_iter().enumerate() {
        let should_expand = match &elem {
            Elem::RepSingle(sym, _) => {
                if i + 1 < total {
                    // Peek is not available after move; handled below via index check.
                    false
                } else {
                    false
                }
            }
            _ => false,
        };
        let _ = should_expand;
        expanded.push(elem);
    }
    // The expansion pass needs lookahead, so it runs on the final vector.
    apply_expansion(expanded)
}

fn apply_expansion(elems: Vec<Elem>) -> Vec<Elem> {
    let mut out: Vec<Elem> = Vec::new();
    for i in 0..elems.len() {
        let elem = &elems[i];
        if let Elem::RepSingle(sym, count) = elem {
            if i + 1 < elems.len() {
                if let Elem::RepBlock(block, _) = &elems[i + 1] {
                    if !block.is_empty() && block[0].first_symbol() == *sym {
                        for _ in 0..*count {
                            out.push(Elem::Atom(*sym));
                        }
                        continue;
                    }
                }
            }
        }
        out.push(elem.clone());
    }
    out
}

pub fn build_regex(test_cases_in: &[String], cfg: &BuilderConfig) -> String {
    let mut test_cases: Vec<String> = test_cases_in.to_vec();
    if cfg.ignore_case {
        for tc in test_cases.iter_mut() {
            let lower = tc.to_lowercase();
            if lower.chars().count() == tc.chars().count() {
                *tc = lower;
            }
        }
    }
    test_cases.sort();
    test_cases.dedup();

    let mut sequences: Vec<Vec<Elem>> = Vec::new();
    for tc in &test_cases {
        let mut symbols: Vec<Symbol> = Vec::new();
        for c in tc.chars() {
            cfg.char_to_symbols(c, &mut symbols);
        }
        let elems = if cfg.repetitions {
            detect_repetitions(&symbols, cfg)
        } else {
            symbols.iter().map(|s| Elem::Atom(*s)).collect()
        };
        sequences.push(elems);
    }

    let non_empty: Vec<Vec<Elem>> = sequences
        .into_iter()
        .filter(|s| !s.is_empty())
        .collect();
    let expr = if non_empty.is_empty() {
        crate::expression::Expr::Eps
    } else {
        dfa::generate_expression(&non_empty)
    };

    let render_cfg = RenderCfg {
        capture: cfg.capture_groups,
        colorize: cfg.colorize,
    };
    let start_anchor = !(cfg.no_start_anchor || cfg.no_anchors);
    let end_anchor = !(cfg.no_end_anchor || cfg.no_anchors);

    if cfg.verbose {
        let mut lines: Vec<String> = Vec::new();
        let prefix = if cfg.ignore_case { "(?ix)" } else { "(?x)" };
        lines.push(col("40;93", prefix, render_cfg));
        if start_anchor {
            lines.push(col("1;33", "^", render_cfg));
        }
        lines.extend(render_verbose(&expr, render_cfg, 1));
        if end_anchor {
            lines.push(col("1;33", "$", render_cfg));
        }
        let _ = group_open(render_cfg);
        let _ = group_close(render_cfg);
        lines.join("\n")
    } else {
        let mut out = String::new();
        if cfg.ignore_case {
            out.push_str(&col("40;93", "(?i)", render_cfg));
        }
        if start_anchor {
            out.push_str(&col("1;33", "^", render_cfg));
        }
        out.push_str(&expr.render_compact(render_cfg, false));
        if end_anchor {
            out.push_str(&col("1;33", "$", render_cfg));
        }
        out
    }
}
EOF
echo ok"}

