use crate::builder::BuilderConfig;
use std::ffi::OsString;
use std::process::exit;

pub const SHORT_HELP: &str = include_str!("help_short.txt");
pub const LONG_HELP: &str = include_str!("help_long.txt");
pub const USAGE: &str = "Usage: grex [OPTIONS] {INPUT...|--file <FILE>}";

#[derive(Clone, Debug, Default)]
pub struct CliArgs {
    pub config: BuilderConfig,
    pub file: Option<OsString>,
    pub inputs: Vec<String>,
    // internal seen tracking is only needed during parsing
}

struct ArgDef {
    long: &'static str,
    display: &'static str, // for error messages, e.g. "--digits" or "--file <FILE>"
    kind: Kind,
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum Kind {
    Digits,
    NonDigits,
    Spaces,
    NonSpaces,
    Words,
    NonWords,
    Escape,
    WithSurrogates,
    Repetitions,
    MinRepetitions,
    MinSubstringLength,
    NoStartAnchor,
    NoEndAnchor,
    NoAnchors,
    Verbose,
    Colorize,
    IgnoreCase,
    CaptureGroups,
    Help,
    Version,
    File,
}

const DEFS: &[ArgDef] = &[
    ArgDef { long: "digits", display: "--digits", kind: Kind::Digits },
    ArgDef { long: "non-digits", display: "--non-digits", kind: Kind::NonDigits },
    ArgDef { long: "spaces", display: "--spaces", kind: Kind::Spaces },
    ArgDef { long: "non-spaces", display: "--non-spaces", kind: Kind::NonSpaces },
    ArgDef { long: "words", display: "--words", kind: Kind::Words },
    ArgDef { long: "non-words", display: "--non-words", kind: Kind::NonWords },
    ArgDef { long: "escape", display: "--escape", kind: Kind::Escape },
    ArgDef { long: "with-surrogates", display: "--with-surrogates", kind: Kind::WithSurrogates },
    ArgDef { long: "repetitions", display: "--repetitions", kind: Kind::Repetitions },
    ArgDef { long: "min-repetitions", display: "--min-repetitions <QUANTITY>", kind: Kind::MinRepetitions },
    ArgDef { long: "min-substring-length", display: "--min-substring-length <LENGTH>", kind: Kind::MinSubstringLength },
    ArgDef { long: "no-start-anchor", display: "--no-start-anchor", kind: Kind::NoStartAnchor },
    ArgDef { long: "no-end-anchor", display: "--no-end-anchor", kind: Kind::NoEndAnchor },
    ArgDef { long: "no-anchors", display: "--no-anchors", kind: Kind::NoAnchors },
    ArgDef { long: "verbose", display: "--verbose", kind: Kind::Verbose },
    ArgDef { long: "colorize", display: "--colorize", kind: Kind::Colorize },
    ArgDef { long: "ignore-case", display: "--ignore-case", kind: Kind::IgnoreCase },
    ArgDef { long: "capture-groups", display: "--capture-groups", kind: Kind::CaptureGroups },
    ArgDef { long: "help", display: "--help", kind: Kind::Help },
    ArgDef { long: "version", display: "--version", kind: Kind::Version },
    ArgDef { long: "file", display: "--file <FILE>", kind: Kind::File },
];

fn find_long(name: &str) -> Option<&'static ArgDef> {
    DEFS.iter().find(|d| d.long == name)
}

fn short_to_kind(ch: char) -> Option<Kind> {
    match ch {
        'd' => Some(Kind::Digits),
        'D' => Some(Kind::NonDigits),
        's' => Some(Kind::Spaces),
        'S' => Some(Kind::NonSpaces),
        'w' => Some(Kind::Words),
        'W' => Some(Kind::NonWords),
        'e' => Some(Kind::Escape),
        'r' => Some(Kind::Repetitions),
        'x' => Some(Kind::Verbose),
        'c' => Some(Kind::Colorize),
        'i' => Some(Kind::IgnoreCase),
        'g' => Some(Kind::CaptureGroups),
        'h' => Some(Kind::Help),
        'v' => Some(Kind::Version),
        'f' => Some(Kind::File),
        _ => None,
    }
}

fn kind_to_def(kind: Kind) -> &'static ArgDef {
    DEFS.iter().find(|d| d.kind == kind).unwrap()
}

fn is_value_taking(kind: Kind) -> bool {
    matches!(kind, Kind::File | Kind::MinRepetitions | Kind::MinSubstringLength)
}

fn err_with_usage(msg: &str) -> ! {
    eprint!("error: {}\n\n{}\n\nFor more information, try '--help'.\n", msg, USAGE);
    exit(2);
}

fn err_without_usage(msg: &str) -> ! {
    eprint!("error: {}\n\nFor more information, try '--help'.\n", msg);
    exit(2);
}

fn duplicate_error(kind: Kind) -> ! {
    let display = kind_to_def(kind).display;
    err_with_usage(&format!("the argument '{}' cannot be used multiple times", display))
}

fn value_required_error(kind: Kind) -> ! {
    let display = kind_to_def(kind).display;
    err_without_usage(&format!("a value is required for '{}' but none was supplied", display))
}

fn unexpected_value_error(kind: Kind, value: &str) -> ! {
    let display = kind_to_def(kind).display;
    err_with_usage(&format!(
        "unexpected value '{}' for '{}' found; no more were expected",
        value, display
    ))
}

fn invalid_value_error(kind: Kind, value: &str, reason: &str) -> ! {
    let display = kind_to_def(kind).display;
    err_without_usage(&format!(
        "invalid value '{}' for '{}': {}",
        value, display, reason
    ))
}

fn invalid_utf8_error() -> ! {
    err_with_usage("invalid UTF-8 was detected in one or more arguments")
}

fn parse_min_value(kind: Kind, value: &str) -> u32 {
    match value.parse::<u32>() {
        Ok(0) => invalid_value_error(kind, value, "Value must not be zero"),
        Ok(v) => v,
        Err(_) => invalid_value_error(kind, value, "Value is not a valid unsigned integer"),
    }
}

#[derive(Default)]
struct Seen {
    digits: bool,
    non_digits: bool,
    spaces: bool,
    non_spaces: bool,
    words: bool,
    non_words: bool,
    escape: bool,
    with_surrogates: bool,
    repetitions: bool,
    min_repetitions: bool,
    min_substring_length: bool,
    no_start_anchor: bool,
    no_end_anchor: bool,
    no_anchors: bool,
    verbose: bool,
    colorize: bool,
    ignore_case: bool,
    capture_groups: bool,
    file: bool,
}

impl Seen {
    fn check_and_mark(&mut self, kind: Kind) -> bool {
        // Returns true if already seen.
        let slot: &mut bool = match kind {
            Kind::Digits => &mut self.digits,
            Kind::NonDigits => &mut self.non_digits,
            Kind::Spaces => &mut self.spaces,
            Kind::NonSpaces => &mut self.non_spaces,
            Kind::Words => &mut self.words,
            Kind::NonWords => &mut self.non_words,
            Kind::Escape => &mut self.escape,
            Kind::WithSurrogates => &mut self.with_surrogates,
            Kind::Repetitions => &mut self.repetitions,
            Kind::MinRepetitions => &mut self.min_repetitions,
            Kind::MinSubstringLength => &mut self.min_substring_length,
            Kind::NoStartAnchor => &mut self.no_start_anchor,
            Kind::NoEndAnchor => &mut self.no_end_anchor,
            Kind::NoAnchors => &mut self.no_anchors,
            Kind::Verbose => &mut self.verbose,
            Kind::Colorize => &mut self.colorize,
            Kind::IgnoreCase => &mut self.ignore_case,
            Kind::CaptureGroups => &mut self.capture_groups,
            Kind::File => &mut self.file,
            Kind::Help | Kind::Version => return false,
        };
        if *slot {
            true
        } else {
            *slot = true;
            false
        }
    }
    fn is_marked(&self, kind: Kind) -> bool {
        match kind {
            Kind::Digits => self.digits,
            Kind::NonDigits => self.non_digits,
            Kind::Spaces => self.spaces,
            Kind::NonSpaces => self.non_spaces,
            Kind::Words => self.words,
            Kind::NonWords => self.non_words,
            Kind::Escape => self.escape,
            Kind::WithSurrogates => self.with_surrogates,
            Kind::Repetitions => self.repetitions,
            Kind::MinRepetitions => self.min_repetitions,
            Kind::MinSubstringLength => self.min_substring_length,
            Kind::NoStartAnchor => self.no_start_anchor,
            Kind::NoEndAnchor => self.no_end_anchor,
            Kind::NoAnchors => self.no_anchors,
            Kind::Verbose => self.verbose,
            Kind::Colorize => self.colorize,
            Kind::IgnoreCase => self.ignore_case,
            Kind::CaptureGroups => self.capture_groups,
            Kind::File => self.file,
            Kind::Help | Kind::Version => false,
        }
    }
}

fn apply_flag(cfg: &mut BuilderConfig, kind: Kind) {
    match kind {
        Kind::Digits => cfg.digits = true,
        Kind::NonDigits => cfg.non_digits = true,
        Kind::Spaces => cfg.spaces = true,
        Kind::NonSpaces => cfg.non_spaces = true,
        Kind::Words => cfg.words = true,
        Kind::NonWords => cfg.non_words = true,
        Kind::Escape => cfg.escape = true,
        Kind::WithSurrogates => cfg.with_surrogates = true,
        Kind::Repetitions => cfg.repetitions = true,
        Kind::NoStartAnchor => cfg.no_start_anchor = true,
        Kind::NoEndAnchor => cfg.no_end_anchor = true,
        Kind::NoAnchors => cfg.no_anchors = true,
        Kind::Verbose => cfg.verbose = true,
        Kind::Colorize => cfg.colorize = true,
        Kind::IgnoreCase => cfg.ignore_case = true,
        Kind::CaptureGroups => cfg.capture_groups = true,
        _ => {}
    }
}

fn is_recognized_flag_token(tok: &str) -> bool {
    if tok == "--" {
        return true;
    }
    if let Some(rest) = tok.strip_prefix("--") {
        let name = rest.split('=').next().unwrap_or("");
        return find_long(name).is_some();
    }
    if tok.starts_with('-') && tok.len() > 1 {
        return tok[1..].chars().all(|c| short_to_kind(c).is_some());
    }
    false
}

fn os_to_string(os: &OsString) -> String {
    match os.clone().into_string() {
        Ok(s) => s,
        Err(_) => invalid_utf8_error(),
    }
}

pub fn parse_args(args: Vec<OsString>) -> CliArgs {
    let mut result = CliArgs::default();
    result.config.min_repetitions = 1;
    result.config.min_substring_length = 1;
    let mut seen = Seen::default();
    let mut inputs_started = false;
    let mut after_double_dash = false;

    let mut i = 0usize;
    while i < args.len() {
        let raw = &args[i];
        if after_double_dash || inputs_started {
            let s = os_to_string(raw);
            result.inputs.push(s);
            i += 1;
            continue;
        }

        // Determine string form, handling invalid UTF-8 like clap.
        let tok: String = match raw.clone().into_string() {
            Ok(s) => s,
            Err(os) => {
                let bytes = os_to_string_lossy_bytes(&os);
                if bytes.starts_with(b"--") {
                    let lossy = String::from_utf8_lossy(&bytes).into_owned();
                    eprint!(
                        "error: unexpected argument '{}' found\n\n  tip: to pass '{}' as a value, use '-- {}'\n\n{}\n\nFor more information, try '--help'.\n",
                        lossy, lossy, lossy, USAGE
                    );
                    exit(2);
                } else {
                    invalid_utf8_error();
                }
            }
        };

        if tok == "--" {
            after_double_dash = true;
            i += 1;
            continue;
        }
        if tok == "-" {
            inputs_started = true;
            result.inputs.push(tok);
            i += 1;
            continue;
        }

        if let Some(rest) = tok.strip_prefix("--") {
            // Long flag/option.
            let (name, eq_value) = match rest.find('=') {
                Some(pos) => (&rest[..pos], Some(rest[pos + 1..].to_string())),
                None => (rest, None),
            };
