                let kind = def.kind;
                if kind == Kind::Help {
                    if let Some(v) = eq_value {
                        unexpected_value_error(kind, &v);
                    }
                    print!("{}", LONG_HELP);
                    exit(0);
                }
                if kind == Kind::Version {
                    if let Some(v) = eq_value {
                        unexpected_value_error(kind, &v);
                    }
                    println!("grex 1.4.6");
                    exit(0);
                }
                if is_value_taking(kind) {
                    if seen.is_marked(kind) {
                        duplicate_error(kind);
                    }
                    let value_os: OsString = if let Some(v) = eq_value {
                        if kind == Kind::File && v.is_empty() {
                            value_required_error(kind);
