                    }
                }
                if consumed_next {
                    i += 1;
                }
                i += 1;
                continue;
            } else {
                inputs_started = true;
                result.inputs.push(tok);
                i += 1;
                continue;
            }
        }

        // Plain positional.
        inputs_started = true;
        result.inputs.push(tok);
        i += 1;
    }

    // Validation.
    if result.file.is_some() && !result.inputs.is_empty() {
        err_with_usage("the argument '--file <FILE>' cannot be used with '[INPUT]...'");
    }
    let mut missing: Vec<&str> = Vec::new();
    if result.config.with_surrogates && !result.config.escape {
        missing.push("--escape");
    }
    if result.file.is_none() && result.inputs.is_empty() {
        missing.push("--file <FILE>");
        missing.push("<INPUT>...");
    }
    if !missing.is_empty() {
        let mut msg = String::from("error: the following required arguments were not provided:\n");
        for m in &missing {
