    match std::fs::read_to_string(path) {
        Ok(contents) => contents.lines().map(|s| s.to_string()).collect(),
        Err(e) => match e.kind() {
            io::ErrorKind::NotFound => {
                eprint_error_and_exit("the specified file could not be found")
            }
            io::ErrorKind::PermissionDenied => {
                eprint_error_and_exit("permission denied: the specified file could not be opened")
            }
            io::ErrorKind::InvalidData => {
                eprint_error_and_exit("the specified file's encoding is not valid UTF-8")
            }
            _ => eprint_error_and_exit(&format!("{}", e)),
        },
    }
}

fn main() {
    let args: Vec<std::ffi::OsString> = std::env::args_os().skip(1).collect();
    let cli = cli::parse_args(args);
    let config = cli.config.clone();

    let test_cases: Vec<String> = if let Some(file_os) = &cli.file {
        let path_buf: std::path::PathBuf = if file_os == "-" {
            // Read filename from stdin.
            let mut stdin_bytes = Vec::new();
            // Read stdin as string with the same error mapping.
            match io::stdin().read_to_end(&mut stdin_bytes) {
                Ok(_) => {}
                Err(e) => {
                    let _ = e;
                    eprint_error_and_exit("the specified file's encoding is not valid UTF-8");
                }
            }
            let content = match String::from_utf8(stdin_bytes) {
                Ok(s) => s,
                Err(_) => {
                    eprint_error_and_exit("the specified file's encoding is not valid UTF-8")
                }
            };
            std::path::PathBuf::from(content.trim().to_string())
        } else {
            std::path::PathBuf::from(file_os.clone())
        };
        read_file_test_cases(&path_buf)
    } else if cli.inputs.len() == 1 && cli.inputs[0] == "-" {
        let mut bytes = Vec::new();
        match io::stdin().read_to_end(&mut bytes) {
            Ok(_) => {}
            Err(e) => {
                panic_like(
                    "src/main.rs:304:38",
                    &format!(
                        "called `Result::unwrap()` on an `Err` value: {:?}",
                        e
                    ),
                );
            }
        }
        match String::from_utf8(bytes) {
            Ok(content) => content.lines().map(|s| s.to_string()).collect(),
            Err(_) => {
                // Mimic an unwrap of a UTF-8 read.
                let err = io::Error::new(
                    io::ErrorKind::InvalidData,
                    "stream did not contain valid UTF-8",
                );
                panic_like(
                    "src/main.rs:304:38",
                    &format!("called `Result::unwrap()` on an `Err` value: {:?}", err),
                );
            }
        }
    } else {
        cli.inputs.clone()
    };

    if test_cases.is_empty() {
        panic_like(
            "/workspace/src/builder.rs:48:13",
            "No test cases have been provided for regular expression generation",
        );
    }

    let result = build_regex(&test_cases, &config);
    println!("{}", result);
}
