def subst(e, var, replacement):
    t=e[0]
    if t=='var':
        return replacement if e[1]==var else e
    if t=='eps' or t=='char' or t=='class': return e
    if t=='alt':
        # fold mk_alt
        members=[subst(m,var,replacement) for m in e[1]]
        if not members: return EPS
        res=members[0]
        for m in members[1:]: res=mk_alt(res,m)
        return res
    if t=='concat':
        res=EPS
        for p in e[1]:
            sp=subst(p,var,replacement)
            res=sp if res==EPS else mk_concat(res,sp)
        return res
    if t=='group': return ('group', subst(e[1],var,replacement))
    if t=='opt': return ('opt', subst(e[1],var,replacement))
    return e

def gen_eq(strings, order_scheme):
    strings=[s for s in strings if s!='']
    if not strings: return "^$"
    state_objs, root = build_min_dfa(strings)
    feats=state_features(state_objs, root)
