    eq={}
    for u,st in state_objs.items():
        terms=[]
        by_target={}
        for ch,v in st.trans.items(): by_target.setdefault(v,[]).append(ch)
        items=[]
        for v,chars in by_target.items():
            chars=sorted(chars)
            if len(chars)==1: sym=Char(chars[0])
            else:
                sym=Char(chars[0])
                for c in chars[1:]: sym=mk_alt(sym,Char(c))
            items.append((chars[0], sym, v))
        items.sort(key=lambda x:x[0])
        for _,sym,v in items:
            var=('var',v)
            term=sym if False else mk_concat(sym,var)
            terms.append(term)
        if st.final: terms.append(EPS)
        if not terms: expr=EPS
        else:
            expr=terms[0]
            for t in terms[1:]: expr=mk_alt(expr,t)
        eq[u]=expr
    # order of elimination (all except root)
    states=list(state_objs.keys())
    bfs=feats['bfs']; height=feats['height']; lang=feats['lang']
    if order_scheme=='height_asc': order=sorted([u for u in states if u!=root], key=lambda u:(height[u], bfs.get(u,999)))
    elif order_scheme=='height_desc': order=sorted([u for u in states if u!=root], key=lambda u:(-height[u], bfs.get(u,999)))
    elif order_scheme=='bfs': order=sorted([u for u in states if u!=root], key=lambda u:bfs.get(u,999))
    elif order_scheme=='bfs_rev': order=sorted([u for u in states if u!=root], key=lambda u:-bfs.get(u,999))
    elif order_scheme=='id': order=[u for u in states if u!=root]
    elif order_scheme=='id_rev': order=list(reversed([u for u in states if u!=root]))
    elif order_scheme=='lang': order=sorted([u for u in states if u!=root], key=lambda u: sorted(lang[u]))
    else: order=[u for u in states if u!=root]
    remaining=dict(eq)
    for v in order:
        if v not in remaining: continue
        expr_v=remaining.pop(v)
        # substitute into all remaining
        for u in list(remaining.keys()):
            remaining[u]=subst(remaining[u], v, expr_v)
    final=remaining.get(root, EPS)
    # final should contain no vars, but if root var remains (none)
    return "^"+print_expr(final)+"$"

if __name__=='__main__':
    CONFIG['factor']='both'; CONFIG['distribute_eps']=False; CONFIG['target_final_leaf']=False; CONFIG['pair_factor']=True; CONFIG['pair_eps_only']=True
    with open('/tmp/dataset.json') as f: data=json.load(f)
