import sys, json
sys.path.insert(0,'/tmp')
import sim
from sim import *

def gen_dyn(strings, keyname):
    strings=[s for s in strings if s!='']
    if not strings: return "^$"
    state_objs, root = build_min_dfa(strings)
    feats=state_features(state_objs, root)
    SS=-1; SF=-2
    edges={}
    def add_edge(i,j,e):
        if (i,j) in edges: edges[(i,j)]=mk_alt(edges[(i,j)], e)
        else: edges[(i,j)]=e
    add_edge(SS, root, EPS)
    for u,st in state_objs.items():
        by_target={}
        for ch,v in st.trans.items(): by_target.setdefault(v,[]).append(ch)
        for v, chars in by_target.items():
            chars=sorted(chars)
            if len(chars)==1: e=Char(chars[0])
            else:
                e=Char(chars[0])
                for c in chars[1:]: e=mk_alt(e, Char(c))
            add_edge(u, v, e)
        if st.final: add_edge(u, SF, EPS)
    remaining=set(state_objs.keys())
    bfs=feats['bfs']; height=feats['height']
    while remaining:
        def keyfn(k):
            preds=set(i for (i,j) in edges if j==k and i!=k)
            succs=set(j for (i,j) in edges if i==k and j!=k)
            npred=len(preds); nsucc=len(succs)
            if keyname=='prod': return (npred*nsucc, npred+nsucc, height[k], bfs.get(k,999))
            if keyname=='sum': return (npred+nsucc, npred*nsucc, height[k], bfs.get(k,999))
            if keyname=='prod_h': return (height[k], npred*nsucc, bfs.get(k,999))
            if keyname=='out': return (nsucc, npred, height[k], bfs.get(k,999))
            if keyname=='in': return (npred, nsucc, height[k], bfs.get(k,999))
            if keyname=='prod_desc_h': return (npred*nsucc, -height[k], bfs.get(k,999))
            if keyname=='maxdeg': return (max(npred,nsucc), npred+nsucc, height[k], bfs.get(k,999))
            return (height[k], bfs.get(k,999))
        k=min(remaining, key=keyfn)
        remaining.remove(k)
        preds=sorted(set(i for (i,j) in list(edges.keys()) if j==k and i!=k), key=lambda u: feats['bfs'].get(u, -999 if u==SS else 999))
        succs=sorted(set(j for (i,j) in list(edges.keys()) if i==k and j!=k), key=lambda u: feats['bfs'].get(u, 999))
        new=[]
        for i in preds:
            for j in succs:
                new.append((i,j,mk_concat(edges[(i,k)], edges[(k,j)])))
        for key in list(edges.keys()):
            if key[0]==k or key[1]==k: del edges[key]
        for i,j,prod in new: add_edge(i,j,prod)
    final=edges.get((SS,SF), EPS)
    return "^"+print_expr(final)+"$"

if __name__=='__main__':
    CONFIG['factor']='both'; CONFIG['distribute_eps']=False; CONFIG['target_final_leaf']=False; CONFIG['pair_factor']=True; CONFIG['pair_eps_only']=True
    with open('/tmp/dataset.json') as f: data=json.load(f)
    for kn in ['prod','sum','prod_h','out','in','prod_desc_h','maxdeg']:
        correct=sum(1 for cases,exp in data if gen_dyn(cases,kn)==exp)
        print(kn,correct)
