import sys, json, itertools, random, time
sys.path.insert(0,'/tmp')
import sim
from sim import *
from collections import deque
CONFIG['factor']='both'; CONFIG['distribute_eps']=False; CONFIG['target_final_leaf']=False; CONFIG['pair_factor']=True; CONFIG['pair_eps_only']=True

def compute_order(state_objs, root, feats, keynames):
    states=list(state_objs.keys())
    bfs=feats['bfs']; height=feats['height']; minlen=feats['minlen']; lang=feats['lang']
    rev={u:[] for u in state_objs}
    for u,st in state_objs.items():
        for ch,v in st.trans.items(): rev[v].append(u)
    leaf=[u for u,st in state_objs.items() if st.final and not st.trans]
    distF={}
    if leaf:
        dq=deque([leaf[0]]); distF[leaf[0]]=0
        while dq:
            u=dq.popleft()
            for p in rev[u]:
                if p not in distF: distF[p]=distF[u]+1; dq.append(p)
    features={
      'h': lambda u: height[u], 'h-': lambda u: -height[u],
      'm': lambda u: minlen[u], 'm-': lambda u: -minlen[u],
      'b': lambda u: bfs.get(u,999), 'b-': lambda u: -bfs.get(u,999),
