      'nt': lambda u: len(state_objs[u].trans), 'nt-': lambda u: -len(state_objs[u].trans),
      'fin': lambda u: 0 if state_objs[u].final else 1, 'fin-': lambda u: 1 if state_objs[u].final else 0,
    }
