    order.sort_by_key(|&u| (*heights.get(&u).unwrap_or(&0), *bfs.get(&u).unwrap_or(&usize::MAX)));"""
new="""    // Compute min lengths and shortest distance (in transitions) to a final state.
    let mut minlens: std::collections::HashMap<usize, u64> = std::collections::HashMap::new();
    for &id in &state_ids {
        // shortest matched length: DP over DAG (transitions have min = max here apart from reps)
        fn compute_min(
            u: usize,
            states: &BTreeMap<usize, State>,
            memo: &mut HashMap<usize, u64>,
            visiting: &mut BTreeSet<usize>,
        ) -> u64 {
            if let Some(&v) = memo.get(&u) { return v; }
            if !visiting.insert(u) { return u64::MAX / 4; }
            let st = states.get(&u).cloned();
            let mut best = if st.as_ref().map(|s| s.is_final).unwrap_or(false) { 0 } else { u64::MAX / 4 };
            if let Some(st) = st {
                for (key, v) in &st.trans {
                    let cand = key.max_len().saturating_add(compute_min(*v, states, memo, visiting));
                    if cand < best { best = cand; }
                }
            }
            visiting.remove(&u);
            memo.insert(u, best);
            best
        }
        let mut memo2 = minlens.clone();
        let v = compute_min(id, &states, &mut memo2, &mut BTreeSet::new());
        minlens = memo2; minlens.insert(id, v);
    }
    let scheme = std::env::var("GREX_TEST_ORDER").unwrap_or_else(|_| "height".to_string());
    let mut order = state_ids.clone();
    match scheme.as_str() {
        "height_nt" => order.sort_by_key(|&u| (*heights.get(&u).unwrap_or(&0), states.get(&u).map(|s| s.trans.len()).unwrap_or(0), *bfs.get(&u).unwrap_or(&usize::MAX))),
        "bfs" => order.sort_by_key(|&u| *bfs.get(&u).unwrap_or(&usize::MAX)),
        "bfs_rev" => order.sort_by_key(|&u| std::cmp::Reverse(*bfs.get(&u).unwrap_or(&0))),
        "id" => order.sort(),
        "id_rev" => { order.sort(); order.reverse(); }
        "min" => order.sort_by_key(|&u| (*minlens.get(&u).unwrap_or(&0), *heights.get(&u).unwrap_or(&0), *bfs.get(&u).unwrap_or(&usize::MAX))),
        "min_bfs" => order.sort_by_key(|&u| (*minlens.get(&u).unwrap_or(&0), *bfs.get(&u).unwrap_or(&usize::MAX))),
        "height_min" => order.sort_by_key(|&u| (*heights.get(&u).unwrap_or(&0), *minlens.get(&u).unwrap_or(&0), *bfs.get(&u).unwrap_or(&usize::MAX))),
        _ => order.sort_by_key(|&u| (*heights.get(&u).unwrap_or(&0), *bfs.get(&u).unwrap_or(&usize::MAX))),
