    add_choice=(variant//12)%3  # 0 smaller, 1 inter, 2 diff
    while W:
        A=W.popleft()
        for c in alphabet:
            X={s for s in range(N) if trans[s][c] in A}
            newP=[]
            for Y in P:
                inter=Y & X; diff=Y - X
                if inter and diff:
                    parts=[inter,diff] if replace_order==0 else [diff,inter]
                    newP.extend(parts)
                    # update W
                    # if Y in W, replace it
                    if Y in W:
                        # remove Y and add parts
                        W=deque([w for w in W if w!=Y])
                        for part in parts: W.append(set(part))
                    else:
                        if add_choice==0:
                            W.append(set(inter) if len(inter)<=len(diff) else set(diff))
                        elif add_choice==1: W.append(set(inter))
                        else: W.append(set(diff))
                else:
                    newP.append(Y)
            P=newP
    # partition index for each original trie node (excluding sink block)
    part_index={}
    for idx,block in enumerate(P):
        for s in block: part_index[s]=idx
    return part_index, nodes

def gen_hop(strings, variant, mode):
    strings=[s for s in strings if s!='']
    if not strings: return "^$"
    part_index, nodes = hop_partition(strings, variant)
    # canonical states from sim's builder: need mapping canonical -> partition index
    # rebuild canonical mapping like build_min_dfa but also return per-state part idx
    # Reuse build_min_dfa then compute each canonical state's trie representatives.
    # build trie again and compute canon ids as in sim (duplicate logic by using its internals? sim.build_min_dfa doesn't expose canon)
    # We'll replicate: nodes_trie
    state_objs, root = build_min_dfa(strings)
    feats=state_features(state_objs, root)
    # Determine partition index for a canonical state by finding a trie node whose suffix language equals state's language
    lang=feats['lang']
    # trie node languages
    # compute language for each trie node from nodes (original hop nodes, excluding sink at end)
    # nodes from hop_partition include sink as last; ignore
    trie_nodes=nodes[:-1]
    # compute node language via recursion
    sys.setrecursionlimit(10000)
    from functools import lru_cache
    # Build children dict
    def node_lang(i):
        # returns frozenset of strings
        res=set()
        if trie_nodes[i][0]: res.add("")
        for ch,child in trie_nodes[i][1].items():
            for suf in node_lang(child): res.add(ch+suf)
        return frozenset(res)
    node_langs=[node_lang(i) for i in range(len(trie_nodes))]
    canon_part={}
    for u in state_objs:
        target=frozenset(lang[u])
        # find node with that language whose partition... choose min partition index among matching
        idxs=[part_index[i] for i in range(len(trie_nodes)) if node_langs[i]==target]
        canon_part[u]=min(idxs) if idxs else 999
    # define eliminate order via sim's machinery by monkeypatching? easier: replicate GNFA from sim.generate but with custom order: we call sim.eliminate_order override
    orig_elim=sim.eliminate_order
    def custom_order(state_objs_, root_, feats_, scheme):
        if mode=='part': return sorted(state_objs_.keys(), key=lambda u: canon_part.get(u,999))
        if mode=='part_rev': return sorted(state_objs_.keys(), key=lambda u: -canon_part.get(u,999))
        if mode=='height_part': return sorted(state_objs_.keys(), key=lambda u: (feats_['height'][u], canon_part.get(u,999)))
        if mode=='height_part_rev': return sorted(state_objs_.keys(), key=lambda u: (feats_['height'][u], -canon_part.get(u,999)))
        return sorted(state_objs_.keys())
    sim.eliminate_order=custom_order
    try:
        result=sim.generate(strings, 'custom')
    finally:
        sim.eliminate_order=orig_elim
    return result

if __name__=='__main__':
    CONFIG['factor']='both'; CONFIG['distribute_eps']=False; CONFIG['target_final_leaf']=False; CONFIG['pair_factor']=True; CONFIG['pair_eps_only']=True
    with open('/tmp/dataset.json') as f: data=json.load(f)
    best=(0,None)
    for variant in range(36):
        for mode in ['part','part_rev','height_part','height_part_rev']:
            correct=0
            for cases,exp in data:
                try: got=gen_hop(cases,variant,mode)
                except Exception as e: got='ERR'
                if got==exp: correct+=1
            if correct>best[0]: best=(correct,(variant,mode)); print("best",best,flush=True)
            else: print(variant,mode,correct)
    print("BEST",best)
