from sim import *

def gen_with_rep_order(strings, mode):
    strings=[s for s in strings if s!='']
    if not strings: return "^$"
    # trie in insertion order (strings as given - dataset sorted)
    nodes=[[False,{}]]
    for s in strings:
        cur=0
        for ch in s:
            nxt=nodes[cur][1].get(ch)
            if nxt is None:
                nxt=len(nodes); nodes.append([False,{}]); nodes[cur][1][ch]=nxt
            cur=nxt
        nodes[cur][0]=True
    state_objs, root = build_min_dfa(strings)
    feats=state_features(state_objs, root)
    lang=feats['lang']
    def node_lang(i):
        res=set()
        if nodes[i][0]: res.add("")
        for ch,child in nodes[i][1].items():
            for suf in node_lang(child): res.add(ch+suf)
        return frozenset(res)
    node_langs=[node_lang(i) for i in range(len(nodes))]
    rep={}
    for u in state_objs:
        target=frozenset(lang[u])
        idxs=[i for i in range(len(nodes)) if node_langs[i]==target]
        rep[u]=min(idxs) if idxs else 9999
        repmax=max(idxs) if idxs else 9999
        rep[(u,'max')]=repmax
    orig=sim.eliminate_order
    def custom(state_objs_, root_, feats_, scheme):
        if mode=='rep': return sorted(state_objs_.keys(), key=lambda u: rep.get(u,9999))
        if mode=='rep_rev': return sorted(state_objs_.keys(), key=lambda u: -rep.get(u,9999))
        if mode=='height_rep': return sorted(state_objs_.keys(), key=lambda u: (feats_['height'][u], rep.get(u,9999)))
        if mode=='height_rep_rev': return sorted(state_objs_.keys(), key=lambda u: (feats_['height'][u], -rep.get(u,9999)))
        if mode=='repmax': return sorted(state_objs_.keys(), key=lambda u: rep.get((u,'max'),9999))
        if mode=='height_repmax': return sorted(state_objs_.keys(), key=lambda u: (feats_['height'][u], rep.get((u,'max'),9999)))
        return list(state_objs_.keys())
    sim.eliminate_order=custom
    try: return sim.generate(strings,'custom')
    finally: sim.eliminate_order=orig

if __name__=='__main__':
    CONFIG['factor']='both'; CONFIG['distribute_eps']=False; CONFIG['target_final_leaf']=False; CONFIG['pair_factor']=True; CONFIG['pair_eps_only']=True
